 if($("purchase-form")){let unitMode=false;const recalc=()=>{if(!$(unitMode?"unit":"paid").value.trim()){$(unitMode?"paid":"unit").value="";return;}const bags=Number($("bags").value.replace(',','.'));if(!(bags>0))return;if(unitMode){const unit=Number($("unit").value.replace(',','.'));$("paid").value=Number.isFinite(unit)?(Math.round(unit*bags*100)/100).toFixed(2):"";}else{const paid=Number($("paid").value.replace(',','.'));$("unit").value=Number.isFinite(paid)?String(Math.round(paid/bags*1e6)/1e6):"";}};$("unit").oninput=()=>{unitMode=true;$("priceMode").value="unit";recalc();};$("paid").oninput=()=>{unitMode=false;$("priceMode").value="total";recalc();};$("bags").oninput=recalc;}
